import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"MAViS: A Multi-Agent Framework for Long-Sequence Video Storytelling","description":"","frontmatter":{"title":"MAViS: A Multi-Agent Framework for Long-Sequence Video Storytelling","arxiv":"2508.08487","date":"2025-08-11","authors":"Qian Wang, Ziqi Huang, Ruoxi Jia, Paul Debevec, Ning Yu","categories":"cs.CV, cs.AI, cs.MA","topics":"智能体视频生成, 长序列叙事, 闭环协调","outline":[2,2]},"headers":[],"relativePath":"papers/2508.08487.md","filePath":"papers/2508.08487.md","lastUpdated":null}'),e={name:"papers/2508.08487.md"};function l(i,s,r,m,c,g){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="mavis-a-multi-agent-framework-for-long-sequence-video-storytelling" tabindex="-1">MAViS: A Multi-Agent Framework for Long-Sequence Video Storytelling <a class="header-anchor" href="#mavis-a-multi-agent-framework-for-long-sequence-video-storytelling" aria-label="Permalink to &quot;MAViS: A Multi-Agent Framework for Long-Sequence Video Storytelling&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2508.08487" target="_blank" rel="noreferrer">2508.08487</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-08-11（本页依据 arXiv HTML <strong>v5</strong>（2026-01-24）全文与附录 A–J 撰写）</td></tr><tr><td><strong>作者</strong></td><td>Qian Wang, Ziqi Huang, Ruoxi Jia, Paul Debevec, Ning Yu（Virginia Tech / NTU / Eyeline Studios）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI, cs.MA</td></tr><tr><td><strong>一句话</strong></td><td>用 explore–examine–enhance 的三步闭环把六个制作阶段串起来，并把「什么样的剧本才生成得出来」写成可执行的写作约束，从生成模型的能力边界反推创作规范。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>长序列视频叙事的难点不在于把一个镜头生成得漂亮，而在于<strong>几十个镜头合起来还成立</strong>：角色不能中途换脸，背景不能在不该变的时候变，动作要能被生成模型真的执行出来，配音要对得上时长。任何一环失手，一分钟的成片就废了。</p><p>MAViS 的问题定义有一个不寻常的角度：它不只问「怎么让 agent 协作」，还问「<strong>什么样的剧本是生成模型执行得了的</strong>」。这是一个在同类工作里几乎没人正面处理的问题——大家默认剧本是自由创作、生成是执行环节，而 MAViS 反过来，把生成器的失败模式量化之后写成剧本阶段的硬约束。</p><p>这件事的价值在于它给出了一条可迁移的方法论：当执行器能力有限时，与其反复重试，不如先把任务空间收缩到执行器的可靠区。论文为此提供了实测数据，而不是凭感觉立规矩，这是全文最值钱的部分。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>多 agent 视频生成</strong>（论文对比的 VideoGen-of-Thought、Mora、MovieAgent）已经建立了「LLM 规划 + 现成生成模型执行」的基本范式。它们的共同不足是流程基本开环：规划阶段产出一次，执行阶段照做，中间没有把生成结果送回去检验规范是否被满足的机制。</p><p><strong>评测与基线的缺口</strong>同样明显。这个任务没有 ground truth 视频，也没有现成 benchmark，因此论文只能自建 20 条用户 prompt。而基线的可比性也需要额外工程：Mora 与 MovieAgent 本身不支持剧本生成，作者用 MAViS 生成的剧本喂给它们；MovieAgent 需要人工训练 LoRA，作者代为训练；三者配同样的图像与视频模型、同样的 GPT-4o。这些细节说明公平比较在这个方向上本身就是一项非平凡的工作。</p><p><strong>更深一层的缺口是「剧本可执行性」从未被量化</strong>。前人默认剧本写什么生成器就能做什么，但实际上「主角走出房门进入客厅」这种空间强关联的镜头对，生成器几乎不可能保持背景一致。MAViS 是第一个把这类失败测出数字、并据此立规矩的工作。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是承认生成模型不是万能执行器。作者做了一批测量而不是猜测：相邻镜头共用同一背景时，VBench 背景一致性只有 <strong>78.42</strong>，而单镜头内部是 <strong>95.88</strong>；空间上强关联的镜头对（门外接屋内这种），只有 <strong>26/100</strong> 被 GPT 判定为背景一致；含复杂动作的镜头 VBench overall consistency 是 <strong>23.25</strong>，简单动作是 <strong>27.76</strong>；镜头里含手机屏幕文字这类细粒度视觉元素时是 <strong>22.68</strong>，不含时是 <strong>27.76</strong>。</p><p>第二步是把这些数字翻译成剧本写作规则：避免相邻镜头同背景、少写紧邻空间的转场、同一角色不要连续出现在相邻镜头、每个镜头只放一个简单动作、不要写细粒度视觉元素、每镜头 5 秒、至少 10 个镜头。</p><p>第三步是验证规则本身有效：无约束时只有 <strong>82/100</strong> 的剧本与用户指令对齐，加上约束后是 <strong>100/100</strong>。这条对照是整套 guidelines 的合法性来源。</p><p>第四步才是 agent 架构。既然每个阶段都可能产出不合规范的结果，就需要一个通用的自检循环，这就是 3E Principle。它被同一套形式复用到六个阶段上，而不是为每个阶段各写一套逻辑。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>长视频叙事失败的根因，一半在生成器不够强，另一半在剧本写了生成器做不到的事。MAViS 同时压这两头：用 explore–examine–enhance 闭环让每个阶段的产出被检验并改写，用从实测数据反推出的剧本约束把任务提前收缩到生成器的可靠区。前者提升执行的成功率，后者降低任务的难度。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>六个阶段</strong>：script writing、shot designing、character modeling、keyframe generation、video animation、audio generation。总映射记为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9468em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2361em;vertical-align:-0.3948em;"></span><span class="mopen">{(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose"><span class="mclose">}</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span></span></span></span>，即从一条用户 prompt 到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个带音频的镜头。</p><p><strong>Script Writing</strong> 由四个 agent 组成：一个 Scriptwriter，加上 Structure / Content / Style 三个 Reviewer，分别对应三份写作指南（Structure Guide、Content Guide、Style Guide）。</p><p><strong>Shot Designing</strong> 把每个镜头拆成<strong>七个要素</strong>：Background、Character Pose、Character Action、Prop Description、Camera Position、Camera Movement、Lighting Design。</p><p><strong>Character Modeling</strong> 包含 Character Prompt Generator、Caption Generator，以及分别针对 T2I 与 I2V 的 Evaluator 与 Refiner。LoRA 训练用 <strong>MUDI</strong>，它支持多主体，因此一个 LoRA 可以服务整个剧本里的所有角色。</p><p><strong>实现细节</strong>：全部 agent 用 <strong>AutoGen</strong> 实现、由 <strong>GPT-4o</strong> 驱动。T2I 池包含 FLUX.1、Stable Diffusion 3.5 与 GPT-Image；I2V 池包含 Veo2、Gen-3、Gen-4、LUMA、HunyuanVideo-I2V 与 Wan2.1；T2A 用 Minimax Hailuo。硬件是<strong>两块 NVIDIA H100</strong>。I2V Evaluator 对每个候选均匀采样 8 帧做判断，视频统一 center-crop 到 1280×720。迭代上限按阶段区分：video animation 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>，shot designing / voice designing / subtitle refining 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>。</p><p><strong>一次完整走法</strong>：用户给一句「一个宇航员在废弃空间站找到一封信」→ Scriptwriter 写出至少 10 个镜头的剧本，三个 Reviewer 分别检查结构、内容与风格，不合规就改写 → Shot Designer 把每个镜头补齐七要素 → Character Modeling 为宇航员生成角色描述并训 MUDI LoRA → keyframe 由 T2I 池生成，Evaluator 打回不合格的 → video animation 用 I2V 池把关键帧动起来，每候选抽 8 帧检验 → 音频阶段生成配音与 BGM，Subtitle Refiner 对齐时长 → 拼接成约一分钟的成片。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化核心是 3E Principle（explore–examine–enhance），写成一个迭代格式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">G</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">r</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 轮的 prompt，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 是该阶段的规范（guideline），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> 是生成器（explore），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 是评估器（examine），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 是改写器（enhance），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是评估反馈。迭代到产出满足 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 为止，或达到该阶段的上限 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span></span></span></span>。</p><p>这个格式值得看的地方有两处。第一，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 同时出现在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 三个函数的输入里——生成、评估、改写共享同一份规范，这保证了三者不会互相拉扯。第二，被更新的是 <strong>prompt</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 而不是模型参数，所以整套机制是 inference-time 的，不需要任何训练。</p><p>代价也在这个式子里：收敛性完全由 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 决定。如果 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span></span></span></span> 判不准，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 就是噪声，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span></span></span></span> 会把 prompt 往错误方向改，迭代次数越多偏得越远。论文把 video animation 阶段的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span></span></span></span> 设成 1（其他阶段是 5），推测正是因为在这个阶段评估器最不可靠，多迭代反而有害——这是基于超参设置的推断，论文未显式给出这个理由。</p><p>总映射 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">P</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9468em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.9468em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.2222em;">V</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2361em;vertical-align:-0.3948em;"></span><span class="mopen">{(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mclose"><span class="mclose">}</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3948em;"><span></span></span></span></span></span></span></span></span></span> 本身没有推导，它只是把「一条 prompt 到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个音画对」这件事写成了记号。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>测试集</strong>：自建 <strong>20 条用户 prompt</strong>，每条目标一分钟视频，因为该任务没有现成 benchmark。基线为 VideoGen-of-Thought、Mora、MovieAgent，配平方式见 §2。</p><p><strong>问题一：自动指标上如何？</strong> Table 2 报 CLIP / Inception / Temporal Flickering / Motion Smoothness / Subject Consistency / Background Consistency / Aesthetic / Imaging Quality。VGoT 22.37 / 8.53 / 99.00 / 99.31 / 98.94 / 98.74 / 80.11 / 64.59；Mora 33.98 / 12.68 / 97.32 / 99.23 / 95.23 / 94.88 / 64.36 / 71.48；MovieAgent 31.71 / 10.72 / 97.07 / 99.20 / 93.29 / 94.51 / 63.39 / 71.26；MAViS <strong>34.22 / 12.81 / 99.09 / 99.53 / 95.72 / 96.12 / 63.17 / 72.91</strong>。</p><p>注意 MAViS 的 subject consistency、background consistency 与 aesthetic <strong>低于 VGoT</strong>。论文的解释是 VGoT 动态弱、画面过饱和，因此在这类指标上占便宜。这个解释与 §11 讨论的 no-op 问题直接相关。</p><p><strong>问题二：人怎么看？</strong> Table 3 是 <strong>60 名评审</strong>的投票，MAViS 在七个维度上全部胜出，平均得票率 <strong>69.44%</strong>（各维度 71.96 / 67.86 / 67.68 / 66.31 / 71.66 / 70.09 / 70.50），VGoT 仅 3.24，Mora 15.29，MovieAgent 10.97。自动指标与人评的巨大反差是全文最有说服力的一组对比。</p><p><strong>问题三：三个 Reviewer 各自有用吗？</strong> Table 4：去掉 Structure Reviewer 得 13.67 / 25.67 / 26.67，去掉 Content Reviewer 得 32.33 / 18.67 / 26.67，去掉 Style Reviewer 得 20.00 / 26.67 / 20.00，完整版 34.00 / 26.00 / 26.67。每去掉一个，对应维度就明显塌陷，交叉验证了三者分工不重叠。</p><p><strong>问题四：3E 闭环值多少？</strong> Table 5：T2I 阶段无 3E 是 31.25 / 10.54 / naturalness 72.00，有 3E 是 34.22 / 12.81 / 98.00；I2V 阶段无 3E 是 32.05 / 11.22 / 60.00，有 3E 是 34.53 / 13.22 / 92.50。<strong>一个例外值得单独记下：Dynamic Degree 在无 3E 时反而更高（44.58 对 35.62）</strong>。论文的推测是高动态更容易出现物理不一致，于是 agent 倾向于选择低动态的稳妥结果。</p><p>整体成功率（定义为无撕裂、无畸变、不违反物理、身份一致、风格一致）有 3E 为 <strong>0.8621</strong>，无 3E 为 <strong>0.4875</strong>。</p><p>Table 6 报 Compliance Rate：去掉 Shot Reviewer 为 84.5，去掉 Voice Reviewer 为 92.0，去掉 Subtitle Refiner 为 56.5，全部加上均为 100.0。</p><p><strong>成本</strong>：两块 H100 上生成一条长视频平均 <strong>13.63 小时</strong>，而内部美术走同样流程需要 5 天。单镜头成本：Veo2 每条 2.8 美元 / 31.7 秒，Gen-3 0.5 美元 / 23.7 秒，Gen-4 0.5 美元 / 40.8 秒，Luma 1.27 美元 / 36.2 秒，HunyuanVideo-I2V 28.7 分钟，Wan2.1 36.3 分钟（后两者各占用一块 H100）。</p><p><strong>常见失败</strong>（论文自陈）：剧本里相邻镜头仍落在同一地点；分镜内容不完整；T2I 出现面部与四肢畸变；I2V 动作异常；BGM 下载失败；配音超出镜头时长。</p><p><strong>论文自陈的 limitation</strong>：只走 T2I + I2V 一条路径，镜头多样性受限；剧情缺少角色对话与互动；没有剪辑机制；<strong>T2I / I2V Evaluator 的可靠性有限</strong>——多模态模型评图能力不足，实用中会外挂 VBench 算子辅助，但实验中为公平比较未启用。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：MAViS 把长视频叙事拆成六个阶段，每个阶段都跑同一套 explore–examine–enhance 闭环，更新的是 prompt 而非模型参数。它把「生成器做不到什么」测成了数字（相邻镜头同背景一致性 78.42 对单镜头 95.88），再据此写成剧本阶段的硬约束。60 人投票里 MAViS 七维全胜、平均得票 69.44%，而 VGoT 只有 3.24。3E 把整体成功率从 0.4875 提到 0.8621，但同时把 Dynamic Degree 从 44.58 压到 35.62。论文自己承认 T2I / I2V Evaluator 可靠性有限，而整套闭环的收敛就靠它。</p><p><strong>3 句话版</strong>：与其重试，不如先把剧本收缩到生成器的可靠区——这是本文最可迁移的思路，且有实测支撑。3E 闭环把每个阶段的产出变成可检验、可改写的对象。代价是系统学会了选「稳」而不是选「好」。</p><p><strong>1 句话版</strong>：从生成模型的失败模式反推创作规范，用一个 inference-time 闭环把它执行下去。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p><strong>假设：T2I / I2V Evaluator 能可靠判断一个候选是否满足规范。</strong> 论文自己在 limitation 里承认这一点存疑，而它承载的重量远超其他任何组件——3E 递推 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span></span></span></span> 里的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 全部由 Evaluator 产生。评估器不准，改写就是随机游走；评估器有系统性偏差，改写就会稳定地把结果推向那个偏差方向。</p><p>这个假设不成立时的失败形态，论文的数据里已经能看到：Dynamic Degree 在加上 3E 后从 44.58 降到 35.62。论文的解释是 agent 偏好低动态的稳妥结果。换个说法就是，Evaluator 更容易在低动态视频里判定「没有物理不一致」，因为低动态视频里根本没有多少物理事件可判。于是闭环在优化「不出错」，而不是在优化「好」。整体成功率的定义（无撕裂、无畸变、不违反物理、身份一致、风格一致）<strong>全部是否定式的</strong>，一段几乎静止的视频天然满足其中大部分条件。0.8621 这个数字因此存在被低动态样本抬高的风险。</p><p>论文提供的对冲是 60 人的用户研究，人评七维全胜且得票率 69.44%，这确实说明最终成片在人眼里明显更好。但用户研究评的是成片整体，无法反推 Evaluator 在单次判断上的准确率。缺失的证据很具体：Evaluator 在一批人工标注的「合格 / 不合格」候选上的准确率与混淆矩阵，以及它在高动态与低动态两个子集上的准确率差异。论文提到实用中会外挂 VBench 算子来补强 Evaluator，这恰恰是作者知道它不够可靠的旁证。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>论文里最容易复现、也最有独立价值的部分是 Script Writing Guidelines 背后的那批测量，它完全不需要跑整套 agent 系统：</p><ol><li>构造 100 组镜头对：50 组共用同一背景，50 组用不同背景；另构造 50 组空间强关联的转场对（门外接屋内）与 50 组无空间关联的对照。</li><li>用任一固定的 T2I + I2V 组合生成，算 VBench 背景一致性，检验能否复现 78.42 对 95.88 这个量级的差距。</li><li>另构造复杂动作 / 简单动作各 50 条、含细粒度视觉元素 / 不含各 50 条，测 VBench overall consistency，对照 23.25 对 27.76 与 22.68 对 27.76。</li><li><strong>关键的额外一步（论文没做）</strong>：对「GPT 判定背景是否一致」这个自动判据做校准——用人工标注的一致 / 不一致镜头对，测 GPT 判断的准确率与偏差方向。26/100 这个数字的可信度完全取决于此。</li></ol><p>判据：若差距量级可复现且 GPT 判据准确率高（比如 AUC 大于 0.85），则整套 guidelines 的实证基础成立，可以直接迁移到别的系统；若 GPT 判据接近随机，则那条 26/100 无意义，相关约束需要重新论证。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释：3E 的收益有相当一部分来自「让视频动得更少」。</strong> 这不是外部揣测，论文表 5 自己给出了 Dynamic Degree 44.58 → 35.62 的下降。设计一个直接攻击：构造一个<strong>平凡基线</strong>——把 MAViS 生成的每个 keyframe 原样保持 5 秒（完全静止，只做轻微推拉），拼成同样长度的一分钟视频，然后在完全相同的自动指标上评测。</p><p>预期结果几乎可以先写出来：这个 no-op 基线在 Temporal Flickering、Motion Smoothness、Subject Consistency、Background Consistency 四项上都会逼近或超过 MAViS。论文里已经有半个证据——VGoT 的这四项是 99.00 / 99.31 / 98.94 / 98.74，全面高于 MAViS 的 99.09 / 99.53 / 95.72 / 96.12 中的后两项，而论文对 VGoT 的解释正是「动态弱」。如果一段完全静止的视频能在四个指标上拿下 MAViS，那么 Table 2 里除 CLIP 与 Inception 之外的列都不应作为核心证据。</p><p><strong>这个反例的建设性用法</strong>是：任何长视频叙事工作都应该把「静止拼接」当作强制汇报的平凡基线，就像分类任务要报 majority class 一样。MAViS 的人评结果（69.44% 对 3.24%）说明它确实远好于 VGoT，但这个结论只由人评支撑，自动指标那一栏在这个问题上是无效的。</p><p><strong>可预测的失败条件</strong>：剧本 guidelines 是从当前一代生成模型的失败模式反推出来的。「同一角色不要连续出现在相邻镜头」「每个镜头只放一个简单动作」这类约束一旦生成模型变强就会成为不必要的枷锁——它会系统性地排除掉双人对话戏、连贯动作戏这些叙事上最重要的镜头类型。论文自陈的 limitation「剧情缺少角色对话与互动」正是这个约束的直接后果。攻击方式：给定一个必须包含两人对话的故事，看 MAViS 的 guidelines 会把它改写成什么——如果对话被拆成互不相邻的独立镜头，那么「100/100 剧本与用户指令对齐」这个数字度量的是「合规」而不是「忠实」。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动它的局限</strong>：guidelines 是硬编码的、静态的，从一次性测量得来。生成模型每半年换一代，这些约束就会同时变得过严（限制叙事）和过松（没覆盖新的失败模式）。而且约束是单向的——只有剧本迁就生成器，生成器从不学习。</p><p><strong>(b) 可借鉴的相邻领域</strong>：机器人学里的 affordance 学习与 curriculum learning。把「生成器能可靠做到什么」建模成一个可学习、可持续更新的能力画像 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal">A</span><span class="mopen">(</span><span class="mord text"><span class="mord">shot</span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，由系统运行中积累的成功 / 失败日志在线拟合。剧本阶段查询这个画像而不是查静态规则；同时，被画像判为低可行性的镜头类型自动进入生成器的微调数据集，形成能力扩张的正反馈。这把「约束创作」变成了「共同进化」。</p><p><strong>(c) 第一个实验</strong>：先做校准与平凡基线两件事。取 500 条镜头描述，覆盖论文那六条约束的正反两面，在固定 I2V 上各生成 3 次，人工标注成败，得到真实的可行性标签。<strong>第一步报告平凡基线</strong>：论文那六条静态规则作为分类器，在这批数据上的准确率是多少——这是任何学习方法必须超过的下限。<strong>第二步做校准</strong>：训一个轻量可行性预测器，报告它的校准曲线（预测概率 0.8 的镜头是否真的约 80% 成功），而不只是准确率。<strong>第三步</strong>才是把预测器接进 Script Writer，对比接入前后在需要复杂镜头（双人对话、连贯动作）的故事上的成片成功率与人评叙事完整度。如果学到的画像不能显著优于六条静态规则，那说明这个方向上真正的瓶颈在生成器而不在规划器，应当把资源投到别处。</p>',65)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
